cd /Users/dradicchi/projects/mvp-leadscorer
duckdb -markdown <<'SQL'
SELECT '=== A1. base de clientes: contagem, setores, paises ===' AS s;
SELECT count(*) AS contas,
       count(DISTINCT sector) AS setores,
       count(DISTINCT office_location) AS paises,
       count(subsidiary_of) AS com_matriz,
       count(*)-count(subsidiary_of) AS sem_matriz
FROM 'data/accounts.csv';

SELECT '=== A2. localizacao (pais) das contas ===' AS s;
SELECT office_location AS pais, count(*) AS contas,
       round(100.0*count(*)/sum(count(*)) OVER (),1) AS pct
FROM 'data/accounts.csv' GROUP BY office_location ORDER BY contas DESC;

SELECT '=== A3. porte: receita e funcionarios (quartis) ===' AS s;
SELECT round(min(revenue),1) AS rev_min, round(quantile_cont(revenue,0.25),1) AS rev_q1,
       round(median(revenue),1) AS rev_mediana, round(quantile_cont(revenue,0.75),1) AS rev_q3,
       round(max(revenue),1) AS rev_max,
       min(employees) AS emp_min, quantile_cont(employees,0.25) AS emp_q1,
       median(employees) AS emp_mediana, quantile_cont(employees,0.75) AS emp_q3,
       max(employees) AS emp_max
FROM 'data/accounts.csv';

SELECT '=== A4. times: gerentes e regioes ===' AS s;
SELECT manager, count(*) AS agentes,
       round(100.0*count(*)/sum(count(*)) OVER (),1) AS pct
FROM 'data/sales_teams.csv' GROUP BY manager ORDER BY agentes DESC;
SELECT '--- por regiao ---' AS s;
SELECT regional_office, count(*) AS agentes FROM 'data/sales_teams.csv'
GROUP BY regional_office ORDER BY agentes DESC;
SQL

cd /Users/dradicchi/projects/mvp-leadscorer
duckdb -markdown <<'SQL'
CREATE OR REPLACE TEMP VIEW pipe AS
  SELECT p.account, p.sales_agent, replace(p.product,'GTXPro','GTX Pro') AS product,
         p.deal_stage, p.close_value
  FROM 'data/sales_pipeline.csv' p;

SELECT '=== F1. Darcel Schlecht x GTK 500 ===' AS s;
SELECT count(*) FILTER (WHERE deal_stage='Won') AS gtk_won,
       count(*) FILTER (WHERE deal_stage='Lost') AS gtk_lost,
       count(*) FILTER (WHERE deal_stage IN ('Engaging','Prospecting')) AS gtk_abertos,
       sum(close_value) FILTER (WHERE deal_stage='Won') AS gtk_receita
FROM pipe WHERE sales_agent='Darcel Schlecht' AND product='GTK 500';

SELECT '=== F2. Darcel: ticket medio com e sem GTK 500 ===' AS s;
SELECT round(avg(close_value) FILTER (WHERE deal_stage='Won'),0) AS ticket_geral,
       round(avg(close_value) FILTER (WHERE deal_stage='Won' AND product='GTK 500'),0) AS ticket_gtk,
       round(avg(close_value) FILTER (WHERE deal_stage='Won' AND product<>'GTK 500'),0) AS ticket_sem_gtk
FROM pipe WHERE sales_agent='Darcel Schlecht';

SELECT '=== F3. quem GANHA o GTK 500 (por agente) ===' AS s;
SELECT sales_agent, count(*) FILTER (WHERE deal_stage='Won') AS gtk_won
FROM pipe WHERE product='GTK 500'
GROUP BY sales_agent HAVING count(*) FILTER (WHERE deal_stage='Won')>0
ORDER BY gtk_won DESC;

SELECT '=== F4. que empresa COMPRA GTK 500 (contas Won) ===' AS s;
SELECT a.account, a.sector, a.revenue, a.employees, a.office_location,
       count(*) AS gtk_won
FROM pipe p JOIN 'data/accounts.csv' a ON a.account=p.account
WHERE p.product='GTK 500' AND p.deal_stage='Won'
GROUP BY a.account, a.sector, a.revenue, a.employees, a.office_location
ORDER BY gtk_won DESC;
SQL

